PINNED.forEach((raw, i) => {
  const cmd = X(raw);
  test(`BLOCK pinned bypass #${i}: ${JSON.stringify(cmd).slice(0, 90)}`, () => {
    const h = makeHome();
    try {
      const r = testHook('git-guard.js', bashPayload(cmd), { home: h.home });
      assert.strictEqual(r.status, 2, `expected block (exit 2) for: ${JSON.stringify(cmd)}\nstderr: ${r.stderr}`);
    } finally {
      h.cleanup();
    }
  });
});

test('block reason names the Write-tool workaround for a heredoc, and only then', () => {
  const h = makeHome();
  try {
    const hd = testHook('git-guard.js', bashPayload(X("python3 - <<'EOF'\ns='BTGP origin v1BT'\nEOF")), { home: h.home });
    assert.strictEqual(hd.status, 2);
    assert.match(hd.stderr, /Heredoc bodies are scanned as shell[\s\S]*Write tool/);
    const plain = testHook('git-guard.js', bashPayload(X('GP origin SUBgit branch --show-current)')), { home: h.home });
    assert.strictEqual(plain.status, 2);
    assert.doesNotMatch(plain.stderr, /Heredoc bodies/);
  } finally {
    h.cleanup();
  }
});
